import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

// Create your useCounter hook here


function CounterA() {
  // Use useCounter(0)
  return (
    <div id="counter-a">
      {/* Display count and buttons */}
    </div>
  );
}

function CounterB() {
  // Use useCounter(10)
  return (
    <div id="counter-b">
      {/* Display count and buttons */}
    </div>
  );
}

function App() {
  return (
    <div>
      <CounterA />
      <CounterB />
    </div>
  );
}

export default App;

