import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('Custom Hooks', () => {
  test('CounterA starts at 0', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#counter-a .count');
if (!el) throw new Error('No .count in #counter-a');
if (el.textContent.trim() !== '0') throw new Error('CounterA should start at 0');
  });

  test('CounterB starts at 10', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#counter-b .count');
if (!el) throw new Error('No .count in #counter-b');
if (el.textContent.trim() !== '10') throw new Error('CounterB should start at 10');
  });

  test('CounterA increment works', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#counter-a .inc');
if (!btn) throw new Error('No .inc button in #counter-a');
btn.click();
await tick();
const el = root.querySelector('#counter-a .count');
if (el.textContent.trim() !== '1') throw new Error('CounterA should be 1 after increment');
  });

  test('Counters are independent', async () => {
    const { container: root } = render(<App />);
    const bCount = root.querySelector('#counter-b .count');
if (bCount.textContent.trim() !== '10')
  throw new Error('CounterB should still be 10 — counters must be independent');
  });

  test('CounterB reset returns to initial value', async () => {
    const { container: root } = render(<App />);
    const incBtn = root.querySelector('#counter-b .inc');
incBtn.click();
await tick();
incBtn.click();
await tick();
const resetBtn = root.querySelector('#counter-b .reset');
if (!resetBtn) throw new Error('No .reset button in #counter-b');
resetBtn.click();
await tick();
const el = root.querySelector('#counter-b .count');
if (el.textContent.trim() !== '10') throw new Error('CounterB should reset to 10');
  });
});
